window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f5dd2e5924b1613a"]={"versions": [{"id": "FIG-f5dd2e5924b1613a", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm nach der AUTOSAR-Methodik-Notation (Methodology / SPEM-basiert). Das Diagramm stellt den Teilschritt der Entwicklung von plattformweiter Anwendungssoftware (<em>Develop Platform-level Application Software</em>) innerhalb der AUTOSAR Adaptive Platform (AP) Methodologie dar und veranschaulicht die ein- und ausgehenden Artefakte (Dateien bzw. Software-Pakete).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Task:</strong>\n<ul class=\"fig-list\"><li><code>Develop Platform-level Application Software</code>: Zentrale Entwicklungsaktivität (dargestellt als abgerundetes Rechteck mit integriertem Methodik-Piktogramm).\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»):</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code>: Standard-Softwarepaket der AUTOSAR Adaptive Platform (Kardinalität <code>0..1</code>).\n</li><li><code>Middleware Library</code>: Dokument-/Bibliotheksartefakt (Kardinalität <code>0..*</code>).\n</li></ul>\n</li><li><strong>Ausgangsartefakte («output»):</strong>\n<ul class=\"fig-list\"><li><code>Platform Object Code</code>: Kompilierter Objektcode der Plattformsoftware (Kardinalität <code>1..*</code>).\n</li><li><code>Main Function</code>: Paket bzw. Codekomponente der Hauptfunktion (Kardinalität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Develop Platform-level Application Software</code> konsumiert optional ein Standardpaket (<code>Autosar AP Standard Package</code>, <code>0..1</code>) sowie eine beliebige Anzahl von Middleware-Bibliotheken (<code>Middleware Library</code>, <code>0..*</code>). Aus diesen Eingangsdaten und dem Implementierungsprozess werden mindestens eine Objektcodedatei (<code>Platform Object Code</code>, <code>1..*</code>) sowie genau eine Instanz bzw. Definition der Hauptfunktion (<code>Main Function</code>, <code>1</code>) erzeugt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die angegebenen Kardinalitäten definieren verbindliche Anforderungen für die Werkzeugkette und den Erstellungsprozess:</p>\n<ul class=\"fig-list\"><li>Das Vorhandensein eines <code>Autosar AP Standard Package</code> ist optional (<code>0..1</code>), ebenso sind zusätzliche Middleware-Bibliotheken optional in beliebiger Anzahl zulässig (<code>0..*</code>).\n</li><li>Die Aktivität muss zwingend mindestens ein Objektcode-Artefakt (<code>Platform Object Code</code>, <code>1..*</code>) und genau eine <code>Main Function</code> (<code>1</code>) liefern. Werkzeuge müssen sicherstellen, dass diese Artefakte im Build- und Integrationspfad bereitgestellt werden.\n</li></ul>"}, {"id": "FIG-b6a6ba67621f95cc", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Aktivitäts- bzw. Prozessdiagramm nach der AUTOSAR-Methodik-Notation (Methodology / SPEM-basiert). Das Diagramm stellt den Teilschritt der Entwicklung von plattformweiter Anwendungssoftware (<em>Develop Platform-level Application Software</em>) innerhalb der AUTOSAR Adaptive Platform (AP) Methodologie dar und veranschaulicht die zugeordneten Akteure/Rollen sowie die ein- und ausgehenden Artefakte (Dateien bzw. Software-Pakete).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Task:</strong>\n<ul class=\"fig-list\"><li><code>Develop Platform-level Application Software</code>: Zentrale Entwicklungsaktivität (dargestellt als abgerundetes Rechteck mit integriertem Methodik-Piktogramm).\n</li></ul>\n</li><li><strong>Akteur / Rolle:</strong>\n<ul class=\"fig-list\"><li><code>Tier 2</code>: Durchführende Organisationseinheit bzw. Akteur, verknüpft über zwei «performs»-Beziehungen mit den Rollenendpunkten:\n<ul class=\"fig-list\"><li><code>+Platform Software Designer</code>\n</li><li><code>+Platform Software Developer</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Eingangsartefakte («input»):</strong>\n<ul class=\"fig-list\"><li><code>Autosar AP Standard Package</code>: Standard-Softwarepaket der AUTOSAR Adaptive Platform (Kardinalität <code>0..1</code>).\n</li><li><code>Middleware Library</code>: Dokument-/Bibliotheksartefakt (Kardinalität <code>0..*</code>).\n</li></ul>\n</li><li><strong>Ausgangsartefakte («output»):</strong>\n<ul class=\"fig-list\"><li><code>Platform Object Code</code>: Kompilierter Objektcode der Plattformsoftware (Kardinalität <code>1..*</code>).\n</li><li><code>Main Function</code>: Paket bzw. Codekomponente der Hauptfunktion (Kardinalität <code>1</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Akteur <code>Tier 2</code> führt die Aktivität <code>Develop Platform-level Application Software</code> in den Rollen <code>+Platform Software Designer</code> und <code>+Platform Software Developer</code> aus («performs»). Die Aktivität konsumiert optional ein Standardpaket (<code>Autosar AP Standard Package</code>, <code>0..1</code>) sowie beliebige Middleware-Bibliotheken (<code>Middleware Library</code>, <code>0..*</code>). Im Prozess werden mindestens ein Objektcode-Artefakt (<code>Platform Object Code</code>, <code>1..*</code>) sowie genau eine Hauptfunktion (<code>Main Function</code>, <code>1</code>) als Ergebnisse generiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung weist der Entwicklungsaktivität explizite Verantwortlichkeiten zu:</p>\n<ul class=\"fig-list\"><li>Die Durchführung obliegt der Partei <code>Tier 2</code>, aufgeteilt auf die Design- und Implementierungsrollen <code>Platform Software Designer</code> und <code>Platform Software Developer</code>.\n</li><li>Prozess- und Werkzeugketten müssen die Rollentrennung bzw. Zuständigkeiten bei der Erzeugung der Artefakte berücksichtigen.\n</li><li>Auf Artefaktebene gilt unverändert: Optionaler Eingang von <code>Autosar AP Standard Package</code> (<code>0..1</code>) und <code>Middleware Library</code> (<code>0..*</code>), verbindliche Erzeugung von mindestens einem <code>Platform Object Code</code> (<code>1..*</code>) und genau einer <code>Main Function</code> (<code>1</code>).\n</li></ul>"}], "trans": [{"from": "FIG-f5dd2e5924b1613a", "to": "FIG-b6a6ba67621f95cc", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neue Rolle / Akteur: <code>Tier 2</code> über zwei «performs»-Assoziationen mit der Aktivität <code>Develop Platform-level Application Software</code> verknüpft.\n</li><li>Neue Rollenenden / Zuständigkeiten an der Aktivität: <code>+Platform Software Designer</code> und <code>+Platform Software Developer</code> als Zielenden der «performs»-Beziehungen von <code>Tier 2</code>.\n</li></ul>"}]};
